#!/usr/bin/env bash
# setup.sh — prepare an isolated workdir for the capped Greenlight MAINNET trial of Alby Hub.
#
# Creates a NEW workdir (refuses if it exists), copies the developer certificate into it with
# 0600 permissions, writes trial.env (mainnet, loopback-only, JIT fee cap) and run.sh, which starts
# the hub with a clean environment so no testnet/regtest variable can leak in.
# It does not start the hub, register a node, or create a seed: the seed is generated by the
# hub's setup screen when you choose Greenlight.
#
# Usage:
#   ./setup.sh --bin-dir DIR --cert-dir DIR [--workdir DIR] [--glcli PATH] [--port N]
#              [--jit-max-fee-sat N] [--network bitcoin|regtest] [--dry-run]
#   --bin-dir   folder with albyhub, libldk_node.so (.dylib on macOS) and SHA256SUMS from build.sh
#   --cert-dir  folder with client.crt and client-key.pem from the Greenlight Developer Console
#   --workdir   default: $HOME/albyhub-greenlight-mainnet-trial
#   --network   default bitcoin. "regtest" exists only to test this script; it skips the cert.
#   --dry-run   print every action, change nothing
set -euo pipefail
umask 077

NETWORK=bitcoin; WORKDIR="$HOME/albyhub-greenlight-mainnet-trial"; BIN_DIR=""; CERT_DIR=""
GLCLI="$(command -v glcli || true)"; PORT=8029; JIT_MAX_FEE_SAT=5000; DRY=0
while [ $# -gt 0 ]; do
  case "$1" in
    --bin-dir) BIN_DIR=$2; shift 2;;
    --cert-dir) CERT_DIR=$2; shift 2;;
    --workdir) WORKDIR=$2; shift 2;;
    --glcli) GLCLI=$2; shift 2;;
    --port) PORT=$2; shift 2;;
    --jit-max-fee-sat) JIT_MAX_FEE_SAT=$2; shift 2;;
    --network) NETWORK=$2; shift 2;;
    --dry-run) DRY=1; shift;;
    -h|--help) sed -n 2,20p "$0"; exit 0;;
    *) echo "unknown option $1" >&2; exit 2;;
  esac
done
die(){ echo "setup.sh: ERROR: $*" >&2; exit 1; }
say(){ echo "setup.sh: $*"; }
do_(){ if [ $DRY = 1 ]; then echo "  [dry-run] $*"; else "$@"; fi; }

case "$NETWORK" in bitcoin|regtest) ;; *) die "--network must be bitcoin (the trial) or regtest (script self-test)";; esac
[[ "$PORT" =~ ^[0-9]+$ ]] && [ "$PORT" -ge 1024 ] && [ "$PORT" -le 65535 ] || die "--port must be 1024-65535"
[[ "$JIT_MAX_FEE_SAT" =~ ^[0-9]+$ ]] || die "--jit-max-fee-sat must be a whole number of sats"
[ "$(id -u)" != 0 ] || die "do not run as root"

# 1. workdir: must be new, absolute, and not inside an existing hub/testnet dir
case "$WORKDIR" in /*) ;; *) WORKDIR="$PWD/$WORKDIR";; esac
[ -e "$WORKDIR" ] && die "$WORKDIR already exists. This script never reuses a workdir (old testnet data or a previous trial). Pick a new --workdir."
PARENT=$(dirname "$WORKDIR"); [ -d "$PARENT" ] || die "parent folder $PARENT does not exist"
p="$PARENT"; while [ "$p" != "/" ]; do
  { [ -f "$p/nwc.db" ] || [ -d "$p/greenlight" ]; } && die "$p looks like an existing Alby Hub workdir; put the trial workdir outside it"
  p=$(dirname "$p")
done
case "$WORKDIR" in *testnet*|*signet*|*regtest*) [ "$NETWORK" = bitcoin ] && die "workdir name mentions a test network; use a distinct mainnet path";; esac

# 2. binaries: present, and matching SHA256SUMS from build.sh
[ -n "$BIN_DIR" ] || die "--bin-dir is required"
BIN_DIR=$(cd "$BIN_DIR" && pwd)
[ -x "$BIN_DIR/albyhub" ] || die "$BIN_DIR/albyhub missing or not executable"
LIB=libldk_node.so; [ "$(uname -s)" = Darwin ] && LIB=libldk_node.dylib
[ -f "$BIN_DIR/$LIB" ] || die "$BIN_DIR/$LIB missing"
[ -f "$BIN_DIR/SHA256SUMS" ] || die "$BIN_DIR/SHA256SUMS missing"
SHA=sha256sum; command -v sha256sum >/dev/null || SHA="shasum -a 256"
( cd "$BIN_DIR" && grep -E " (albyhub|$LIB)\$" SHA256SUMS | $SHA -c --quiet - ) || die "checksum mismatch in $BIN_DIR"
say "binaries verified against $BIN_DIR/SHA256SUMS ($(grep -h '^commit=' "$BIN_DIR/BUILDINFO.txt" 2>/dev/null || echo 'commit unknown'))"

# 3. glcli >= 0.1.3 with signer --backup-path
[ -n "$GLCLI" ] && [ -x "$GLCLI" ] || die "glcli not found; pass --glcli /path/to/glcli (see PLAN.md step 0.4)"
GLCLI=$(cd "$(dirname "$GLCLI")" && pwd)/$(basename "$GLCLI")
"$GLCLI" signer run --help 2>/dev/null | grep -q -- --backup-path || die "$GLCLI lacks 'signer run --backup-path'; build gl-cli 0.1.3+ from source (PLAN.md 0.4)"
say "glcli: $("$GLCLI" --version 2>/dev/null)"

# 4. developer certificate (never printed)
if [ "$NETWORK" = bitcoin ]; then
  [ -n "$CERT_DIR" ] || die "--cert-dir is required for mainnet"
  for f in client.crt client-key.pem; do [ -s "$CERT_DIR/$f" ] || die "$CERT_DIR/$f missing or empty"; done
  grep -q "BEGIN CERTIFICATE" "$CERT_DIR/client.crt" || die "client.crt is not a PEM certificate"
  grep -q "PRIVATE KEY" "$CERT_DIR/client-key.pem" || die "client-key.pem is not a PEM private key"
fi

# 5. no stray dev/test variables in this shell (run.sh starts from a clean env anyway)
for v in GL_SCHEDULER_GRPC_URI GL_CA_CRT GL_NOBODY_CRT GL_NOBODY_KEY GREENLIGHT_XPAY_PREDELAY_MS GREENLIGHT_CREDS_PATH GREENLIGHT_NODE_URI GREENLIGHT_SIGNER_DATA_DIR LDK_NETWORK NETWORK WORK_DIR; do
  [ -n "${!v:-}" ] && say "note: $v is set in this shell; run.sh ignores it (clean environment)"
done

say "creating $WORKDIR (network=$NETWORK, http://127.0.0.1:$PORT, JIT fee cap ${JIT_MAX_FEE_SAT} sats)"
do_ mkdir -m 700 "$WORKDIR"
do_ mkdir -m 700 "$WORKDIR/devcert" "$WORKDIR/evidence"
if [ "$NETWORK" = bitcoin ]; then
  do_ install -m 600 "$CERT_DIR/client.crt" "$WORKDIR/devcert/client.crt"
  do_ install -m 600 "$CERT_DIR/client-key.pem" "$WORKDIR/devcert/client-key.pem"
fi

ENV_BODY="# generated by setup.sh $(date -u +%Y-%m-%dT%H:%M:%SZ). Loaded by run.sh only.
NETWORK=$NETWORK
LN_BACKEND_TYPE=GREENLIGHT
WORK_DIR=$WORKDIR
PORT=127.0.0.1:$PORT
LOG_LEVEL=5
GREENLIGHT_GLCLI_PATH=$GLCLI
GL_NOBODY_CRT=$WORKDIR/devcert/client.crt
GL_NOBODY_KEY=$WORKDIR/devcert/client-key.pem
GREENLIGHT_JIT_MAX_FEE_SAT=$JIT_MAX_FEE_SAT
GREENLIGHT_REFUSE_JIT_AFTER_LSP_VIOLATION=true
SEND_EVENTS_TO_ALBY=false
AUTO_LINK_ALBY_ACCOUNT=false
LD_LIBRARY_PATH=$BIN_DIR
DYLD_LIBRARY_PATH=$BIN_DIR
HUB_BIN=$BIN_DIR/albyhub"

RUN_BODY='#!/usr/bin/env bash
# run.sh — start the trial hub with a clean environment (only trial.env + HOME/PATH).
set -euo pipefail
umask 077
D=$(cd "$(dirname "$0")" && pwd)
[ "$(stat -c %a "$D" 2>/dev/null || stat -f %Lp "$D")" = 700 ] || { echo "workdir permissions changed; expected 700" >&2; exit 1; }
if pgrep -f "glcli.*signer run" >/dev/null 2>&1; then echo "WARNING: a glcli signer is already running on this machine. Two signers for one node must never run; stop other hubs first." >&2; fi
ENVV=(); while IFS= read -r l; do case "$l" in ""|\#*) ;; *) ENVV+=("$l");; esac; done < "$D/trial.env"
BIN=$(grep "^HUB_BIN=" "$D/trial.env" | cut -d= -f2-)
echo "starting hub; UI at http://$(grep "^PORT=" "$D/trial.env" | cut -d= -f2-)  (log: $D/log/)"
exec env -i HOME="$HOME" PATH="/usr/local/bin:/usr/bin:/bin:/opt/homebrew/bin" TERM="${TERM:-xterm}" "${ENVV[@]}" "$BIN"
'

CHECK_BODY='#!/usr/bin/env bash
# check.sh — confirm the hub listens on loopback only and the workdir is private.
D=$(cd "$(dirname "$0")" && pwd); P=$(grep "^PORT=" "$D/trial.env" | cut -d= -f2-); PORTN=${P##*:}
ok=1
if command -v ss >/dev/null; then L=$(ss -ltnH "sport = :$PORTN" | awk "{print \$4}"); else L=$(lsof -nP -iTCP:"$PORTN" -sTCP:LISTEN 2>/dev/null | awk "NR>1{print \$9}"); fi
[ -n "$L" ] || { echo "nothing listening on port $PORTN"; ok=0; }
for a in $L; do case "$a" in 127.0.0.1:*) echo "listen $a OK";; *) echo "listen $a NOT LOOPBACK"; ok=0;; esac; done
bad=$(find "$D" \( -type d ! -perm 700 \) -o \( -type f \( -perm -040 -o -perm -004 -o -perm -020 -o -perm -002 \) \) 2>/dev/null)
[ -z "$bad" ] && echo "permissions OK (dirs 700, files no group/other access)" || { echo "loose permissions:"; echo "$bad"; ok=0; }
[ $ok = 1 ] && echo "CHECK PASSED" || { echo "CHECK FAILED"; exit 1; }
'

if [ $DRY = 1 ]; then
  echo "  [dry-run] write $WORKDIR/trial.env (0600):"; echo "$ENV_BODY" | sed 's/^/      /'
  echo "  [dry-run] write $WORKDIR/run.sh and $WORKDIR/check.sh (0700)"
else
  printf '%s\n' "$ENV_BODY" > "$WORKDIR/trial.env"; chmod 600 "$WORKDIR/trial.env"
  printf '%s' "$RUN_BODY" > "$WORKDIR/run.sh"; printf '%s' "$CHECK_BODY" > "$WORKDIR/check.sh"
  chmod 700 "$WORKDIR/run.sh" "$WORKDIR/check.sh"
fi
say "done. Next: $WORKDIR/run.sh, open http://127.0.0.1:$PORT, choose Greenlight (PLAN.md step 1). Then run $WORKDIR/check.sh."
